"""Android CPython smoke test for the Legendary host runtime prerequisites.

Run inside CPython's upstream Android testbed with:
    python3 Platforms/Android test --managed maxVersion \
      --site-packages epicbridge/poc/site-packages -- -m epic_runtime_smoke
"""
import certifi
import ctypes
import fcntl
import hashlib
import mmap
import os
import requests
import sqlite3
import ssl
import subprocess
import tempfile
from threading import Thread
import zlib

assert ctypes.sizeof(ctypes.c_void_p) == 8, "expected 64-bit Android process"
assert hashlib.sha256(b"maliwinlator").hexdigest()
payload = b"legendary-runtime-zlib-probe" * 32
assert zlib.decompress(zlib.compress(payload)) == payload

# The Android Legendary downloader shares an anonymous mmap between threads.
shared = mmap.mmap(-1, 1024 * 1024, access=mmap.ACCESS_WRITE)
def mmap_writer(offset, value):
    shared[offset:offset + 8] = value * 8
threads = [Thread(target=mmap_writer, args=(i * 64, bytes([i + 1]))) for i in range(8)]
for thread in threads:
    thread.start()
for thread in threads:
    thread.join(timeout=5)
    assert not thread.is_alive(), "mmap worker thread did not finish"
for i in range(8):
    assert shared[i * 64:i * 64 + 8] == bytes([i + 1]) * 8
shared.close()

with sqlite3.connect(":memory:") as db:
    db.execute("create table probe (value text)")
    db.execute("insert into probe values (?)", ("ok",))
    assert db.execute("select value from probe").fetchone()[0] == "ok"

# Legendary's downloader/auth endpoints require working DNS, CA trust and TLS.
context = ssl.create_default_context(cafile=certifi.where())
assert context.verify_mode == ssl.CERT_REQUIRED
response = requests.get("https://legendary.gl", timeout=20)
assert 200 <= response.status_code < 400, response.status_code

# filelock's POSIX implementation relies on advisory file locks.
with tempfile.TemporaryFile() as lock_file:
    fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)

# Verify Android Bionic process creation without depending on a shell.
proc = subprocess.run(
    ["/system/bin/echo", "EPIC_SUBPROCESS_OK"],
    check=True, capture_output=True, text=True, timeout=10,
)
assert "EPIC_SUBPROCESS_OK" in proc.stdout, proc.stdout

print("EPIC_ANDROID_RUNTIME_PREREQUISITES_OK")
